import java.util.*;

public class Solution {
    public int nextBeautifulNumber(int n) {
        int maxLen = 9; // consider compositions with total digits up to 9
        long ans = Long.MAX_VALUE;
        // digits 1..9 mapped to bits 0..8
        for (int mask = 1; mask < (1 << 9); mask++) {
            int sumLen = 0;
            for (int d = 1; d <= 9; d++) {
                if (((mask >> (d - 1)) & 1) == 1) sumLen += d;
            }
            if (sumLen == 0 || sumLen > maxLen) continue;
            int[] digits = new int[sumLen];
            int idx = 0;
            for (int d = 1; d <= 9; d++) {
                if (((mask >> (d - 1)) & 1) == 1) {
                    for (int k = 0; k < d; k++) digits[idx++] = d;
                }
            }
            Arrays.sort(digits);
            // generate all unique permutations
            do {
                long val = 0;
                for (int x : digits) {
                    val = val * 10 + x;
                    if (val > ans) break; // no need to continue if already not better
                }
                if (val > n && val < ans) ans = val;
            } while (nextPermutation(digits));
        }
        return (int) ans;
    }

    private boolean nextPermutation(int[] a) {
        int n = a.length;
        int i = n - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i < 0) return false;
        int j = n - 1;
        while (a[j] <= a[i]) j--;
        swap(a, i, j);
        reverse(a, i + 1, n - 1);
        return true;
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i]; a[i] = a[j]; a[j] = t;
    }

    private void reverse(int[] a, int l, int r) {
        while (l < r) {
            swap(a, l++, r--);
        }
    }
}

